//! 🟰️ Exact optional dictionaries and intrinsic values compare borrowed original fields through funded paged pair frames.
use super::QuestionDictionary;
use semio_framework_value::{DslValue,Number,RetirementDemand,ValueError,ValueRefusalKind,retirement::RetireOwned,retained_clone::{RetainedCloneRef,RetainedCloneBinding,RetainedCloneGrant,RetainedCloneProgress,RetainedCloneStep,retained_clone_grant_admits}};
use semio_framework_value_persistent::{list::PagedList,RetainedEqualityStep};
use std::mem::size_of;
/// 🪞️ Only the first-party source representation selects the initial borrowed comparison role.
pub enum QuestionEqualityRoot<'a>{Dictionary(Option<&'a QuestionDictionary>),Value(&'a DslValue)}
pub trait QuestionEqualitySource:RetireOwned+Send+Sync+'static{fn equality_root(&self)->QuestionEqualityRoot<'_>;}
impl QuestionEqualitySource for Option<QuestionDictionary>{fn equality_root(&self)->QuestionEqualityRoot<'_>{QuestionEqualityRoot::Dictionary(self.as_ref())}}
impl QuestionEqualitySource for QuestionDictionary{fn equality_root(&self)->QuestionEqualityRoot<'_>{QuestionEqualityRoot::Dictionary(Some(self))}}
impl QuestionEqualitySource for DslValue{fn equality_root(&self)->QuestionEqualityRoot<'_>{QuestionEqualityRoot::Value(self)}}
#[derive(Clone,Copy)]enum Pair{Dictionary(&'static QuestionDictionary,&'static QuestionDictionary),Value(&'static DslValue,&'static DslValue),Text(&'static str,&'static str),Bytes(&'static[u8],&'static[u8])}
#[derive(Clone,Copy)]struct Frame{pair:Pair,at:usize,phase:u8}
impl Frame{fn new(pair:Pair)->Self{Self{pair,at:0,phase:0}}}
fn fault(message:&'static str)->ValueError{ValueError::literal(ValueRefusalKind::InvariantViolated,message)}
/// 🧳️ Source bindings keep every original pair loan live until pending/stack slots and page allocations are closed.
pub struct BorrowedQuestionEquality<S:QuestionEqualitySource>{left:Option<RetainedCloneBinding>,right:Option<RetainedCloneBinding>,frames:PagedList<Frame,{usize::MAX}>,pending:Option<Frame>,started:bool,result:Option<bool>,closing:bool,rebinding:bool,marker:std::marker::PhantomData<fn()->S>}
pub type QuestionDictionaryEqualityCursor=BorrowedQuestionEquality<Option<QuestionDictionary>>;
pub type QuestionValueEqualityCursor=BorrowedQuestionEquality<DslValue>;
impl<S:QuestionEqualitySource> Default for BorrowedQuestionEquality<S>{fn default()->Self{Self::new()}}
impl<S:QuestionEqualitySource> BorrowedQuestionEquality<S>{
 const FIXED:usize=size_of::<Self>()*2;
 pub fn new()->Self{Self{left:None,right:None,frames:Default::default(),pending:None,started:false,result:None,closing:false,rebinding:false,marker:Default::default()}}
 pub fn result(&self)->Option<bool>{self.result}
 pub fn verify(&self,left:RetainedCloneRef<'_,S>,right:RetainedCloneRef<'_,S>)->Result<(),ValueError>{left.check_binding(&self.left)?;right.check_binding(&self.right)?;Ok(())}
 pub fn verify_original(&self,right:RetainedCloneRef<'_,S>)->Result<(),ValueError>{if self.right.is_none(){return Err(fault("Question equality has no original right source"))}right.check_binding(&self.right)?;Ok(())}
 fn nested(d:RetirementDemand)->Result<RetirementDemand,ValueError>{Ok(RetirementDemand{copy_bytes:d.copy_bytes.checked_add(Self::FIXED).ok_or_else(||fault("Question equality copy extent overflow"))?,depth:d.depth.checked_add(1).ok_or_else(||fault("Question equality depth overflow"))?,..d})}
 fn child(g:RetainedCloneGrant)->RetainedCloneGrant{RetainedCloneGrant{maximum_copy_bytes:g.maximum_copy_bytes.saturating_sub(Self::FIXED),maximum_depth:g.maximum_depth.saturating_sub(1),..g}}
 fn receipt(mut p:RetainedCloneProgress)->RetainedCloneProgress{p.copied_items=p.copied_items.max(1);p.copied_bytes+=Self::FIXED;p}
 fn failure(error:ValueError)->ValueError{let p=Self::receipt(error.retained_progress());error.with_retained_progress(p)}
 fn work(&self)->RetirementDemand{RetirementDemand{copy_bytes:size_of::<Frame>()*2+512,depth:self.frames.len().max(1),..Default::default()}}
 pub fn demand(&self,left:RetainedCloneRef<'_,S>,right:RetainedCloneRef<'_,S>,_body:usize)->Result<RetirementDemand,ValueError>{self.verify(left,right)?;if self.closing||self.rebinding||self.result.is_some(){return Err(fault("Question equality is closing or settled"))}if self.left.is_none(){return Self::nested(left.binding_demand(&self.left)?.unwrap_or_default())}if self.right.is_none(){return Self::nested(right.binding_demand(&self.right)?.unwrap_or_default())}if self.pending.is_some()&&!self.frames.has_reserved_slot(){return Self::nested(RetirementDemand{copy_bytes:self.frames.next_reserve_copy_byte_demand().map_err(|_|fault("Question equality page extent overflow"))?,capacity_bytes:self.frames.next_allocation_bytes().map_err(|_|fault("Question equality page extent overflow"))?,depth:self.frames.next_reserve_depth_demand().map_err(|_|fault("Question equality page depth overflow"))?.max(self.frames.len()+1),..Default::default()})}Self::nested(self.work())}
 pub fn next_demand(&self,left:RetainedCloneRef<'_,S>,right:RetainedCloneRef<'_,S>,body:usize)->Result<RetirementDemand,ValueError>{self.demand(left,right,body)}
 /// 🪢️ The two genuine issued aliases cover these immutable loans until funded child-first closure.
 pub fn advance(&mut self,left:RetainedCloneRef<'_,S>,right:RetainedCloneRef<'_,S>,g:RetainedCloneGrant)->Result<RetainedEqualityStep,ValueError>{let d=self.demand(left,right,g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedEqualityStep{equal:None,progress:Default::default()})}if self.left.is_none(){let p=left.bind(&mut self.left,Self::child(g)).map_err(Self::failure)?.unwrap_or_default();return Ok(RetainedEqualityStep{equal:None,progress:Self::receipt(p)})}if self.right.is_none(){let p=right.bind(&mut self.right,Self::child(g)).map_err(Self::failure)?.unwrap_or_default();return Ok(RetainedEqualityStep{equal:None,progress:Self::receipt(p)})}let mut progress=RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()};if !self.started{self.started=true;let a:QuestionEqualityRoot<'static>=unsafe{std::mem::transmute(left.get().equality_root())};let b:QuestionEqualityRoot<'static>=unsafe{std::mem::transmute(right.get().equality_root())};match(a,b){(QuestionEqualityRoot::Dictionary(None),QuestionEqualityRoot::Dictionary(None))=>self.result=Some(true),(QuestionEqualityRoot::Dictionary(Some(a)),QuestionEqualityRoot::Dictionary(Some(b)))=>self.pending=Some(Frame::new(Pair::Dictionary(a,b))),(QuestionEqualityRoot::Value(a),QuestionEqualityRoot::Value(b))=>self.pending=Some(Frame::new(Pair::Value(a,b))),_=>self.result=Some(false)}}else if self.pending.is_some()&&!self.frames.has_reserved_slot(){progress=Self::receipt(self.frames.reserve_one_funded(Self::child(g)).map_err(|e|fault("Question equality frontier allocation failed").with_retained_progress(RetainedCloneProgress{retained_capacity_bytes:e.allocated_bytes,..Default::default()})).map_err(Self::failure)?)}else if let Some(frame)=self.pending.take(){self.frames.push_reserved(frame).map_err(|_|fault("Question equality admitted frontier slot vanished").with_retained_progress(progress))?}else{self.step();}Ok(RetainedEqualityStep{equal:self.result,progress})}
 fn finish_frame(&mut self){self.frames.pop();if self.frames.is_empty(){self.result=Some(true)}}
 fn step(&mut self){let last=self.frames.len()-1;let frame=self.frames[last];match frame.pair{
 Pair::Dictionary(a,b)=>{if a.entries.len()!=b.entries.len(){self.result=Some(false)}else if frame.at==a.entries.len(){self.finish_frame()}else{let a=&a.entries[frame.at];let b=&b.entries[frame.at];if frame.phase==0{self.frames[last].phase=1;self.pending=Some(Frame::new(Pair::Text(&a.question_id,&b.question_id)))}else{self.frames[last].phase=0;self.frames[last].at+=1;self.pending=Some(Frame::new(Pair::Value(&a.value,&b.value)))}}},
 Pair::Text(a,b)=>self.bytes(last,a.as_bytes(),b.as_bytes(),frame.at),Pair::Bytes(a,b)=>self.bytes(last,a,b,frame.at),
 Pair::Value(a,b)=>match(a,b){(DslValue::Array(a),DslValue::Array(b))=>{if a.len()!=b.len(){self.result=Some(false)}else if frame.at==a.len(){self.finish_frame()}else{self.frames[last].at+=1;self.pending=Some(Frame::new(Pair::Value(&a[frame.at],&b[frame.at])))}},(DslValue::Object(a),DslValue::Object(b))=>{if a.len()!=b.len(){self.result=Some(false)}else if frame.at==a.len(){self.finish_frame()}else{let(a,b)=(&a[frame.at],&b[frame.at]);if frame.phase==0{self.frames[last].phase=1;self.pending=Some(Frame::new(Pair::Text(&a.0,&b.0)))}else{self.frames[last].phase=0;self.frames[last].at+=1;self.pending=Some(Frame::new(Pair::Value(&a.1,&b.1)))}}},(DslValue::String(a),DslValue::String(b))=>{self.frames[last]=Frame::new(Pair::Text(a,b))},(DslValue::Bytes(a),DslValue::Bytes(b))=>{self.frames[last]=Frame::new(Pair::Bytes(a,b))},_=>{let equal=match(a,b){(DslValue::Null,DslValue::Null)=>true,(DslValue::Bool(a),DslValue::Bool(b))=>a==b,(DslValue::Number(Number::UInt(a)),DslValue::Number(Number::UInt(b)))=>a==b,(DslValue::Number(Number::Int(a)),DslValue::Number(Number::Int(b)))=>a==b,(DslValue::Number(Number::Float(a)),DslValue::Number(Number::Float(b)))=>a.to_bits()==b.to_bits(),_=>false};if equal{self.finish_frame()}else{self.result=Some(false)}}}}
 }
 fn bytes(&mut self,last:usize,a:&[u8],b:&[u8],at:usize){if a.len()!=b.len(){self.result=Some(false);return}let end=a.len().min(at.saturating_add(256));if a[at..end]!=b[at..end]{self.result=Some(false)}else if end==a.len(){self.finish_frame()}else{self.frames[last].at=end}}
 pub fn ready_to_bind(&self)->bool{!self.closing&&!self.rebinding&&!self.started&&self.result.is_none()&&self.left.is_none()&&self.right.is_none()&&self.pending.is_none()&&self.frames.is_empty()}
 pub fn begin_rebind(&mut self)->Result<(),ValueError>{if self.closing||self.rebinding||self.result.is_none(){return Err(fault("Question equality rebind requires a settled original pair"))}self.rebinding=true;Ok(())}
 pub fn rebind_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.rebinding||self.closing{return Err(fault("Question equality rebind has not begun"))}if self.pending.is_some()||!self.frames.is_empty(){return Self::nested(RetirementDemand{copy_bytes:size_of::<Frame>(),depth:self.frames.len().max(1),..Default::default()})}if self.left.is_some()||self.right.is_some(){return Self::nested(RetainedCloneBinding::close_demand(if self.right.is_some(){&self.right}else{&self.left},body.saturating_sub(Self::FIXED))?)}Ok(RetirementDemand{copy_bytes:Self::FIXED,depth:1,..Default::default()})}
 /// 🔄️ Retire prior borrowed slots and aliases under the original grant while retaining empty page capacity for the next source pair.
 pub fn rebind_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.rebind_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.pending.take().is_some()||self.frames.pop().is_some(){return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if self.left.is_some()||self.right.is_some(){let step=RetainedCloneBinding::close_one(if self.right.is_some(){&mut self.right}else{&mut self.left},Self::child(g)).map_err(Self::failure)?;return Ok(RetainedCloneStep::Progress(Self::receipt(step.progress())))}self.started=false;self.result=None;self.rebinding=false;Ok(RetainedCloneStep::Complete(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}
 pub fn begin_close(&mut self){self.closing=true;self.rebinding=false}
 pub fn close_demand(&self,body:usize)->Result<RetirementDemand,ValueError>{if !self.closing{return Err(fault("Question equality close has not begun"))}if self.pending.is_some()||!self.frames.is_empty(){return Self::nested(RetirementDemand{copy_bytes:size_of::<Frame>(),depth:self.frames.len().max(1),..Default::default()})}if !self.frames.terminal_is_empty(){return Self::nested(RetirementDemand{release_bytes:self.frames.next_release_allocation_bytes().map_err(|_|fault("Question equality close page extent overflow"))?,depth:self.frames.next_release_depth_demand().map_err(|_|fault("Question equality close page depth overflow"))?.max(1),..Default::default()})}Self::nested(RetainedCloneBinding::close_demand(if self.right.is_some(){&self.right}else{&self.left},body.saturating_sub(Self::FIXED))?)}
 pub fn close_step(&mut self,g:RetainedCloneGrant)->Result<RetainedCloneStep,ValueError>{let d=self.close_demand(g.maximum_copy_bytes)?;if !retained_clone_grant_admits(g,d){return Ok(RetainedCloneStep::Progress(Default::default()))}if self.pending.take().is_some()||self.frames.pop().is_some(){return Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,copied_bytes:d.copy_bytes,..Default::default()}))}if !self.frames.terminal_is_empty(){let p=self.frames.release_empty_page(Self::child(g).maximum_release_bytes).map_err(|_|fault("Question equality backing release failed"))?;return Ok(RetainedCloneStep::Progress(Self::receipt(RetainedCloneProgress{copied_items:usize::from(p.progressed),released_bytes:p.released_allocation_bytes,..Default::default()})))}let step=RetainedCloneBinding::close_one(if self.right.is_some(){&mut self.right}else{&mut self.left},Self::child(g)).map_err(Self::failure)?;let p=Self::receipt(step.progress());Ok(if self.terminal_is_empty(){RetainedCloneStep::Complete(p)}else{RetainedCloneStep::Progress(p)})}
 pub fn terminal_is_empty(&self)->bool{self.pending.is_none()&&self.frames.terminal_is_empty()&&self.left.is_none()&&self.right.is_none()}
}
impl<S:QuestionEqualitySource> Drop for BorrowedQuestionEquality<S>{fn drop(&mut self){assert!(std::thread::panicking()||self.terminal_is_empty(),"Question equality retains original aliases and frontier until funded close")}}
#[cfg(test)]#[path="🧪️tests.rs"]mod tests;
